  {
    "taxonId": 50619,
    "summary": "Bulbous herbaceous perennials native to temperate parts of the Northern Hemisphere, from the Mediterranean and North Africa across Eurasia to western North America. They die back after flowering and regrow from underground bulbs, typically bearing nodding, bell-shaped flowers.",
    "humanEdibility": "yes",
    "edibilityNote": "Bulbs of a few species are edible if carefully prepared and were commonly eaten by Indigenous Pacific Northwest peoples; most fritillaries have poisonous bulbs.",
    "evidence": {
      "summary": ["s1:p2", "s1:p6"],
      "humanEdibility": ["s1:p94", "s1:p96"]
    }
  },
  {
    "taxonId": 50630,
    "summary": "Annual or perennial herbs and subshrubs native to temperate Eurasia, North Africa, Macaronesia and North America south to Costa Rica. Wallflowers have distinctive star-shaped or forked hairs, warm-coloured flowers and pods containing many seeds.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p3", "s1:p6"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 50716,
    "summary": "Terrestrial orchids of temperate and subtropical America, Asia and Europe; giant helleborine is the only species native to the Americas. Creeping fleshy underground stems send up new shoots in spring, bearing terminal clusters of flowers ranging from greenish-white to violet and purple.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p3", "s1:p5", "s1:p9"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 50791,
    "summary": "Annual and perennial herbs native to temperate Europe, northern Africa and Asia, with greatest diversity around the Mediterranean. Several species are garden plants, while some spread readily or become troublesome weeds.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p5", "s1:p6", "s1:p9"],
      "humanEdibility": []
    }
  },
