    "summary": "Mostly deciduous trees native to warm-temperate and subtropical North America, the Caribbean and East Asia. They have large heart-shaped leaves, broad clusters of showy white-to-yellow flowers and long pods filled with flat, winged seeds.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p4"],
      "humanEdibility": []
    }
  },
