    "taxonId": 50921,
    "summary": "Perennial bulbous plants native to Eurasia, including the Mediterranean basin and parts of Europe, North Africa and Asia. Their spring flower spikes are densely packed with usually blue, urn-shaped blooms resembling bunches of grapes.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p1", "s1:p10"],
      "humanEdibility": []
    }
